#!/usr/bin/env python3
"""Generate triage.html (repo root): every Backdrop thumbnail on one page, click to
mark scenes for removal, export the marked list. For the manual keep/prune pass over
the 84-scene library. Selection persists in localStorage; thumbnails are referenced
by relative path (not embedded) so re-rendered scenes show current pixels on reload.

Run:  python3 scripts/make_triage_page.py   # then open triage.html in a browser
"""
import html as html_mod
import json
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(HERE)
THUMBS = os.path.join(REPO, "Float/Resources/Textures/Backdrop/Thumbnails")
THUMBS_REL = "Float/Resources/Textures/Backdrop/Thumbnails"
CATALOG = os.path.join(REPO, "Float/Immersive/SpatialImageEnvironment.swift")
AUTO = os.path.join(REPO, "upscale/deepsky_auto.json")
OUT = os.path.join(REPO, "triage.html")
# Original-master previews for the POTM cards, so render quality can be judged
# against the source. Generated from the archive drive; skipped when unmounted.
ARCHIVE_POTM = "/Volumes/Logic Pro/Float Originals Archive/potm"
ORIG_DIR = os.path.join(REPO, "triage_originals")
ORIG_REL = "triage_originals"

GROUPS = [  # (label, predicate on scene name) — first match wins
    ("Grounded", ("spatial_rogland", "spatial_dikhololo", "spatial_paranal",
                  "spatial_lasilla")),
    ("All-sky maps (SPHEREx / unWISE)", ("spatial_spherex", "spatial_unwise")),
    ("Deep space (Shutterstock + star map)",
     ("spatial_dual_nebula", "spatial_blue_filaments", "spatial_teal_orange",
      "spatial_dark_dust", "spatial_pale_haze", "spatial_deep_star_map")),
    ("Deep-sky masters (hand-tuned)",
     ("spatial_carina_mystic", "spatial_m16_pillars", "spatial_m8_lagoon",
      "spatial_s106_angel", "spatial_m104_sombrero", "spatial_m106_spiral",
      "spatial_ngc4631_whale", "spatial_m31_andromeda")),
    ("POTM / hand-picked (auto-placed)", ()),          # catch-all
]


def ensure_original_thumbs(pids):
    """Make triage_originals/<pid>.jpg (512px long side) from the archived masters.
    Returns the set of pids that have a preview available."""
    from PIL import Image
    Image.MAX_IMAGE_PIXELS = None
    have = set()
    missing = []
    for pid in pids:
        dst = os.path.join(ORIG_DIR, f"{pid}.jpg")
        if os.path.exists(dst):
            have.add(pid)
            continue
        src = next((os.path.join(ARCHIVE_POTM, pid + e)
                    for e in (".tif", ".png", ".jpg")
                    if os.path.exists(os.path.join(ARCHIVE_POTM, pid + e))), None)
        if not src:
            missing.append(pid)
            continue
        os.makedirs(ORIG_DIR, exist_ok=True)
        im = Image.open(src).convert("RGB")
        im.thumbnail((512, 512), Image.LANCZOS)
        im.save(dst, quality=85)
        have.add(pid)
    if missing:
        print(f"no archive original for: {', '.join(missing)}"
              + ("" if os.path.isdir(ARCHIVE_POTM) else "  (archive not mounted)"))
    return have


def bust(rel):
    """Append ?v=<mtime> to an image URL.

    Without this a re-rendered scene does not show. The filename never changes, so the
    browser serves its cached copy and the page silently displays the PREVIOUS render —
    which is exactly what happened to m31 after it was rebuilt from the Hubble mosaic:
    the card was correct, the pixels on screen were stale. Keyed on mtime, so it only
    changes when the file does and marks in localStorage (keyed on data-name) survive.
    """
    p = os.path.join(REPO, rel)
    try:
        return f"{rel}?v={int(os.path.getmtime(p))}"
    except OSError:
        return rel


# Planet geometry-test cards. These live in the MAIN list (Rick's call from the headset —
# they were in their own trailing section and he wants them among everything else), placed
# in the star-map group because that is the backdrop they are now composited over.
PLANET_GROUP = "Deep space (Shutterstock + star map)"
PLANET_PREV_REL = "upscale/planet_prev"
PLANETS = [
    ("saturn", "Saturn &mdash; live lighting",
     "8192 map (4096 real under SR) &middot; honest to ~29&deg; &middot; rings span 2.27 R "
     "&middot; <b>rings now actually light up</b>: the ring normal is (0.449, 0.893, 0.000) "
     "and the old key light gave N&middot;L = <b>&minus;0.039</b> &mdash; the sun sat 2.2&deg; "
     "off the ring PLANE, lighting the annulus edge-on, so it rendered black. The sun is now "
     "26.7&deg; off the view axis (12.7&deg; right, 23.7&deg; up) giving N&middot;L = "
     "<b>+0.449</b>, which is the hard PHYSICAL ceiling: the rings lie in Saturn's equator, so "
     "the sun is never more than 26.7&deg; above them. Since N_z = 0, ring brightness is "
     "independent of the sun's depth &mdash; putting it behind the viewer costs nothing"),
    ("saturn_baked", "Saturn &mdash; ring shadow baked",
     "Cycles bake at 8192, globe unlit &middot; measured mean diff from the live card "
     "0.25/255 &middot; <b>its rings were invisible for a second, unrelated reason</b>: the "
     "annulus is a separate un-baked diffuse material and the body was flagged "
     "<code>unlit</code>, so it received no light at all. The app now lights every body; the "
     "baked globe has diffuseColor (0,0,0) so it cannot respond &middot; caveat: with the sun "
     "behind the viewer the ring shadow falls behind the rings, so the bake's feature no "
     "longer reads &mdash; the two Saturn cards will look alike for a NEW reason"),
    ("jupiter", "Jupiter &mdash; Cassini + Juno",
     "14400 REAL (Bj&ouml;rn J&oacute;nsson) vs 4096 for the artist texture it replaces "
     "&middot; honest to ~62&deg;, the sharpest body here &middot; spun to put the Great Red "
     "Spot on the visible face &middot; graded +35% sat, +0.15 contrast &middot; poles partly "
     "synthetic where Juno data was blended in &middot; redistribution resolved: repo goes "
     "private (see CREDITS.md)"),
    ("iapetus", "Iapetus &mdash; colour mosaic",
     "11741 real Cassini/Voyager colour &middot; honest to ~59&deg; &middot; the two-tone "
     "split (bright trailing side vs dark Cassini Regio) is the point &middot; known defects: "
     "smeared poles, mosaic seams, green cast near the terminator"),
    ("venus", "Venus",
     "8192 real (SSS surface) &middot; honest to ~47&deg; &middot; retrograde, so north "
     "reads inverted"),
]

# Grounded source panoramas that are NOT scenes yet — no render exists, so they carry the
# source pixels and the findings needed to decide whether to build them.
CANDIDATE_GROUP = "Grounded"
CANDIDATES = [
    ("cand_deathvalley_playa", "triage_originals/cand_deathvalley_playa.jpg",
     "Death Valley &mdash; Racetrack Playa, Milky&nbsp;Way arch",
     "4000&times;1290 (3.10:1) &middot; <b>Dan Duriscoe, U.S. National Park Service, 2005</b> "
     "&middot; <span class=\"ok\">public domain</span> (US federal work) &middot; via APOD "
     "2007-05-08"
     "<br><span class=\"ok\">360&deg; wrap CONFIRMED</span> &mdash; seam 7.44 vs 6.12 for "
     "adjacent interior columns (22.8 = unrelated pair)"
     "<br><span class=\"warn\">SHOWN COLOURISED &mdash; the colour is INVENTED.</span> The "
     "source is an NPS night-sky-monitoring mosaic: 30 frames through a V-band photometric "
     "filter on a mono CCD, saturation exactly 0.00000 on all three Commons variants. No "
     "colour version exists or can. This is SD1.5 chroma at denoise 0.50 over the original "
     "luminance (luma drift 0.000/255, so every star and crack is the real data), with the "
     "blue plume above the sailing stone patched out. Credit accordingly if it ships"
     "<br>Horizon at row 936/1290 &mdash; zenith and nadir both missing, needs cap outpaint. "
     "Vertical mapping still UNSOLVED (APOD's wording says equirect; star shapes disagree)"),
    ("cand_bontecou_lake", "triage_originals/cand_bontecou_lake.jpg",
     "Bontecou Lake &mdash; Milky&nbsp;Way over water",
     "9640&times;3949 (2.44:1) &middot; Nikon D750, 15mm, 25s, f/2.8, ISO&nbsp;6400 &middot; "
     "2017-06-21"
     "<br><span class=\"warn\">NOT 360&deg;</span> &mdash; seam 20.5 vs 4.87 adjacent "
     "(26.5 = unrelated pair). A real gap, but far closer to closing than a random pair"
     "<br>Geometry solved: <b>cylindrical, 350&deg; horizontal, 57.6&deg; above / 42.8&deg; "
     "below the horizon</b> &mdash; fit predicts 3948px vs actual 3949 (equirect ruled out)"
     "<br>Needs cylindrical&rarr;equirect remap (lat = atan(y/k), exact, no GPU), then "
     "outpaint of three gaps only: a 10&deg; wedge behind the camera, zenith cap, nadir cap"
     "<br><span class=\"warn\">CC BY-SA 4.0, Artist &quot;Juliancolton&quot; &mdash; "
     "attribution REQUIRED</span>, add to CREDITS.md"),
]

EXTRA_CSS = """
  /* Candidate cards show a SOURCE panorama. The default .card img crops to 2/1 with
     object-fit:cover, which would hide exactly what has to be judged — the left/right
     edges and the sky/ground split. So: full width, true aspect, no crop, no cap. */
  .card img.pano { aspect-ratio:auto; object-fit:contain; background:#000; max-height:none; }
  .card.cand figcaption { color:#9a9aa4; }
  .card.cand figcaption .spec { display:block; margin-top:4px; color:#7a7a84;
                                font:11px/1.45 ui-monospace, monospace; }
  .card figcaption .warn { color:#e8a33d; }
  .card figcaption .ok { color:#7fc98a; }
"""


def planet_card(name, title, note):
    return (f'<figure class="card" data-name="planet_{name}" onclick="toggle(this)">'
            f'<div class="lbl">geometry test</div>'
            f'<img loading="lazy" src="{bust(f"{PLANET_PREV_REL}/{name}.jpg")}" alt="{name}">'
            f'<div class="tag">REMOVE</div>'
            f'<figcaption><b>{title}</b><br>{note}</figcaption></figure>')


def candidate_card(key, rel, title, spec):
    return (f'<figure class="card cand" data-name="{key}" onclick="toggle(this)">'
            f'<div class="lbl">source panorama &middot; no render yet</div>'
            f'<img loading="lazy" class="pano" src="{bust(rel)}" alt="{title}">'
            f'<div class="tag">REMOVE</div>'
            f'<figcaption><b>{key.removeprefix("cand_")}</b><br>{title}'
            f'<span class="spec">{spec}</span></figcaption></figure>')


def titles_from_catalog():
    t = {}
    src = open(CATALOG).read()
    for m in re.finditer(r'\.init\(name:\s*"([^"]+)",\s*title:\s*"([^"]+)"', src):
        t[m.group(1)] = m.group(2)
    return t


def main():
    titles = titles_from_catalog()
    if os.path.exists(AUTO):
        for r in json.load(open(AUTO)):
            titles.setdefault(r["name"], r.get("title", ""))
    scenes = sorted(os.path.splitext(f)[0] for f in os.listdir(THUMBS)
                    if f.endswith(".jpg"))
    grouped = {label: [] for label, _ in GROUPS}
    for s in scenes:
        for label, prefixes in GROUPS:
            if not prefixes or any(s.startswith(p) for p in prefixes):
                grouped[label].append(s)
                break

    potm_label = GROUPS[-1][0]
    with_orig = ensure_original_thumbs(
        [s.removeprefix("spatial_") for s in grouped[potm_label]])

    # Cards that are not scene thumbnails but belong in the main grouped list.
    extras = {label: [] for label, _ in GROUPS}
    extras[CANDIDATE_GROUP] += [candidate_card(*c) for c in CANDIDATES]
    extras[PLANET_GROUP] += [planet_card(*p) for p in PLANETS
                             if os.path.exists(os.path.join(REPO, PLANET_PREV_REL,
                                                            f"{p[0]}.jpg"))]

    cards = []
    for label, _ in GROUPS:
        n = len(grouped[label]) + len(extras[label])
        if not n:
            continue
        cards.append(f'<h2>{html_mod.escape(label)} '
                     f'<span class="n">({n})</span></h2>'
                     f'<div class="grid">')
        for s in grouped[label]:
            title = html_mod.escape(titles.get(s, ""))
            pid = s.removeprefix("spatial_")
            orig = (f'<div class="lbl">master</div>'
                    f'<img loading="lazy" class="orig" '
                    f'src="{bust(f"{ORIG_REL}/{pid}.jpg")}" alt="">'
                    if label == potm_label and pid in with_orig else "")
            lbl = '<div class="lbl">render</div>' if orig else ""
            cards.append(
                f'<figure class="card" data-name="{s}" onclick="toggle(this)">'
                f'{lbl}<img loading="lazy" src="{bust(f"{THUMBS_REL}/{s}.jpg")}" alt="{s}">'
                f'{orig}<div class="tag">REMOVE</div>'
                f'<figcaption><b>{pid}</b>'
                f'{"<br>" + title if title else ""}</figcaption></figure>')
        cards += extras[label]
        cards.append("</div>")

    page = """<!doctype html><html><head><meta charset="utf-8">
<title>Float backdrop triage</title>
<style>
  :root { color-scheme: dark; }
  body { background:#101014; color:#ddd; margin:0 0 130px 0;
         font:14px/1.4 -apple-system, system-ui, sans-serif; }
  header { position:sticky; top:0; background:#101014e6; backdrop-filter:blur(6px);
           padding:12px 20px; z-index:2; border-bottom:1px solid #26262e; }
  h1 { font-size:17px; margin:0; } h1 small { color:#888; font-weight:400; }
  h2 { margin:26px 20px 10px; font-size:15px; color:#bbb; } h2 .n { color:#666; }
  .grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr));
          gap:12px; padding:0 20px; }
  .card { position:relative; margin:0; cursor:pointer; border-radius:8px;
          overflow:hidden; background:#17171c; outline:2px solid transparent; }
  .card img { width:100%; aspect-ratio:2/1; object-fit:cover; display:block; }
  .card img.orig { aspect-ratio:auto; max-height:170px; object-fit:contain;
                   background:#000; border-top:1px solid #26262e; }
  .card .lbl { font-size:10px; letter-spacing:.08em; text-transform:uppercase;
               color:#777; padding:3px 9px 2px; background:#131318; }
  .card figcaption { padding:6px 9px 8px; color:#aaa; }
  .card figcaption b { color:#ddd; font-weight:600; }
  .card .tag { position:absolute; top:8px; right:8px; background:#d33;
               color:#fff; font-weight:700; font-size:12px; padding:2px 8px;
               border-radius:4px; display:none; }
  .card.removed { outline-color:#d33; }
  .card.removed img { filter:grayscale(.9) brightness(.45); }
  .card.removed .tag { display:block; }
  footer { position:fixed; bottom:0; left:0; right:0; background:#17171cf2;
           border-top:1px solid #26262e; padding:10px 20px;
           display:flex; gap:14px; align-items:center; }
  footer textarea { flex:1; height:64px; background:#101014; color:#e88;
                    border:1px solid #333; border-radius:6px; padding:6px 8px;
                    font:12px ui-monospace, monospace; resize:none; }
  footer button { background:#2a2a33; color:#ddd; border:1px solid #444;
                  border-radius:6px; padding:8px 14px; cursor:pointer; }
  footer button:hover { background:#34343e; }
  #count { min-width:110px; color:#e88; font-weight:600; }
__EXTRA_CSS__
</style></head><body>
<header><h1>Float backdrop triage <span id="stats"></span> <small>— click a card to
mark it for removal; selection persists in this browser</small></h1></header>
__CARDS__
<footer>
  <div id="count"></div>
  <textarea id="list" readonly spellcheck="false"></textarea>
  <button onclick="copyList()">Copy list</button>
  <button onclick="saveList()">Save list</button>
  <button onclick="clearAll()">Clear all</button>
</footer>
<script>
const KEY = "float-triage-removed";
let removed = new Set(JSON.parse(localStorage.getItem(KEY) || "[]"));
// Drop marks for scenes no longer on the page (already pruned in an earlier batch).
const onPage = new Set([...document.querySelectorAll(".card")].map(c => c.dataset.name));
removed = new Set([...removed].filter(n => onPage.has(n)));
document.querySelectorAll(".card").forEach(c => {
  if (removed.has(c.dataset.name)) c.classList.add("removed");
});
function sync() {
  localStorage.setItem(KEY, JSON.stringify([...removed]));
  document.getElementById("count").textContent =
    removed.size + " marked · " + (onPage.size - removed.size) + " kept";
  document.getElementById("list").value = [...removed].sort().join("\\n");
}
function saveList() {
  const blob = new Blob([document.getElementById("list").value + "\\n"],
                        {type: "text/plain"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "triage_removed.txt";
  a.click();
}
function toggle(c) {
  const n = c.dataset.name;
  removed.has(n) ? removed.delete(n) : removed.add(n);
  c.classList.toggle("removed");
  sync();
}
function copyList() {
  const t = document.getElementById("list");
  t.select(); document.execCommand("copy");
}
function clearAll() {
  if (!confirm("Clear all marks?")) return;
  removed.clear();
  document.querySelectorAll(".card.removed").forEach(c => c.classList.remove("removed"));
  sync();
}
sync();
</script></body></html>"""
    with open(OUT, "w") as f:
        f.write(page.replace("__EXTRA_CSS__", EXTRA_CSS)
                    .replace("__CARDS__", "\n".join(cards)))
    print(f"{len(scenes)} scenes -> {OUT}")


if __name__ == "__main__":
    main()

